			return;
		global::UnityEngine.Vector2Int grid = player.gridPosition;
		switch (CheckWallDir(zoneData.ZoneID, grid))
		{
			case 0: grid.y = grid.y + 1; break;
			case 1: grid.y = grid.y - 1; break;
			case 2: grid.x = grid.x + 1; break;
			case 3: grid.x = grid.x - 1; break;
			case -1: return;
		}
		switch (CheckWallDir(zoneData.ZoneID, grid))
		{
			case 0: grid.y = grid.y + 1; break;
			case 1: grid.y = grid.y - 1; break;
			case 2: grid.x = grid.x + 1; break;
			case 3: grid.x = grid.x - 1; break;
			case -1: player.gridPositionDirect = grid; return;
		}
		switch (CheckWallDir(zoneData.ZoneID, grid))
		{
			case 0: grid.y = grid.y + 1; break;
			case 1: grid.y = grid.y - 1; break;
			case 2: grid.x = grid.x + 1; break;
			case 3: grid.x = grid.x - 1; break;
			case -1: player.gridPositionDirect = grid; return;
		}

		int CheckWallDir(global::ZoneID zoneId, global::UnityEngine.Vector2Int centerGrid)
		{
			global::UnityEngine.Vector2Int g = centerGrid;
			g.x = centerGrid.x - 1;
			if (!CanEntryAttribute(zoneId, g))
