			g.x = centerGrid.x + 1;
			if (!CanEntryAttribute(zoneId, g))
				return 3;
			g.x = centerGrid.x;
			g.y = centerGrid.y - 1;
			if (!CanEntryAttribute(zoneId, g))
				return 0;
			g.y = centerGrid.y + 1;
			if (!CanEntryAttribute(zoneId, g))
